  step("fluids-first", "Fluids before insulin", "Hour 1", ["Adults: 1 L of 0.9% saline over the first hour, then 250–500 mL/hour (ICMR STW).", "Never start insulin before intravenous fluids (ICMR STW pitfalls).", "Older adults and patients with heart or kidney failure: use smaller boluses such as 250 mL and reassess (2024 consensus)."], [("Child or adolescent", ["0.9% saline 10–20 mL/kg over 20–30 minutes; 20 mL/kg if perfusion is poor; then replace the deficit over 24–48 hours (ISPAD 2022)."])]),
